import{_ as s,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const c=JSON.parse('{"title":"SeqBench: Benchmarking Sequential Narrative Generation in Text-to-Video Models","description":"","frontmatter":{"title":"SeqBench: Benchmarking Sequential Narrative Generation in Text-to-Video Models","arxiv":"2510.13042","date":"2025-10-14","authors":"Zhengxu Tang, Zizheng Wang, Luning Wang, Zitao Shuai, Chenhao Zhang, Siyu Qian, Yirui Wu, Bohao Wang, Haosong Rao, Zhenyu Yang, Chenwei Wu","categories":"cs.CV, cs.AI","topics":"物理感知视频生成, 叙事一致性, 视频生成评测","outline":[2,2]},"headers":[],"relativePath":"papers/2510.13042.md","filePath":"papers/2510.13042.md","lastUpdated":null}'),r={name:"papers/2510.13042.md"};function p(o,a,i,l,h,g){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="seqbench-benchmarking-sequential-narrative-generation-in-text-to-video-models" tabindex="-1">SeqBench: Benchmarking Sequential Narrative Generation in Text-to-Video Models <a class="header-anchor" href="#seqbench-benchmarking-sequential-narrative-generation-in-text-to-video-models" aria-label="Permalink to &quot;SeqBench: Benchmarking Sequential Narrative Generation in Text-to-Video Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2510.13042" target="_blank" rel="noreferrer">2510.13042</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-10-14</td></tr><tr><td><strong>作者</strong></td><td>Zhengxu Tang, Zizheng Wang, Luning Wang, Zitao Shuai, Chenhao Zhang, Siyu Qian, Yirui Wu, Bohao Wang, Haosong Rao, Zhenyu Yang, Chenwei Wu</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>用按「主体数 × 动作数 × 时序类型」分层设计的 320 条 prompt 与 2560 条人工标注视频，配合把 prompt 解析成时序依赖 DAG、再用问题自适应的场景图提取与依赖过滤打分的 DTG 指标，量化 T2V 模型「画面好看但叙事崩」的程度。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>现在的文生视频模型能把「狗在雪地里玩耍」「城市日落」这类单一场景拍得很漂亮。但一旦 prompt 变成「护士先取药、再走到病床、然后给病人注射」这种多事件序列，模型就开始出错：护士的衣服颜色中途变了、救人发生在跑过去之前、液体颜色的转变顺序反了、动作被执行在错误的主体身上。论文开篇的 Fig. 1 就是这四类失败的直接展示。</p><p>这件事重要，是因为叙事连贯性正在成为落地瓶颈。数字内容创作场景里，用户要的不是一个 3 秒的漂亮片段，而是能讲清一件事的视频。同时这也是物理与因果理解的代理任务——「先倾倒搅拌机再洒出果汁」这个顺序是物理因果决定的，模型把它反过来，说明它没有把事件之间的依赖关系建模进去。</p><p>第二个问题同样关键：<strong>怎么自动测</strong>。人工标注 2560 条视频代价极高，不可持续；而现成的 MLLM 评测方法在长序列上力有不逮。所以论文实际上问了两个问题——当前模型在序列叙事上有多差，以及如何设计一个既捕捉长程依赖又算得动的自动指标。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>评测侧</strong>。现有 T2V benchmark（VBench++、T2VEval、AIGC 视频质量评估等）聚焦物体保真度、帧间过渡、物理一致性和文本-视频对齐，测的是「画面层面」的质量。作者的批评很直接：它们<strong>忽略了人类叙事的根本维度——事件如何随时间连贯展开</strong>。</p><p><strong>MLLM 自动评测侧</strong>，论文列出四条具体不足。第一，多数 MLLM 受算力与能力限制无法处理整段视频，因而捕捉不到跨越长序列的依赖与顺序。第二，很多方法完全不管序列结构，只做帧级评估，而帧级评估天然测不出时序连贯性。第三，一些方法重度依赖关键帧检测，会漏掉动作之间的过渡细节——恰恰是过渡处最容易出错。第四，最接近的 StoryEval 只考虑<strong>事件完成率</strong>，完全不管事件顺序、后果准确性与动作间的逻辑一致性。</p><p>也就是说，「多事件视频生成好不好」这个问题此前既没有分层设计的测试集，也没有能读出顺序错误的指标。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是把「叙事连贯」这个模糊概念拆成可操作的维度。观察失败案例可以归纳出两个正交轴：<strong>主体数量</strong>（一个还是多个）与<strong>动作数量</strong>（单个还是多个）。这两个轴的组合天然给出四档难度。再加一个轴——多个动作之间的时序关系是严格有序、可任意顺序、还是同时发生——就构成完整的分层设计。分层的价值在于它让「模型在哪一维上崩」可诊断，而不是给出一个笼统的总分。</p><p>第二步是 prompt 的可行性约束。公开 T2V 模型大多只能生成 10 秒以内的视频，多数 CLIP 文本编码器只吃 77 token。所以每条 prompt 只能容纳 1–4 个动作，且每个动作要能在 1–5 秒内完成。这些不是设计偏好，是硬边界。</p><p>第三步是指标。既然 MLLM 处理不了整段视频，就必须降采样到有限帧；但降采样又会丢掉过渡细节。折中方案是：<strong>把 prompt 侧的结构先解析出来</strong>，形成一个事件依赖图，再拿着这张图去有针对性地看少数几帧。这样帧数受限的劣势被结构化的问题设计部分抵消。</p><p>第四步是打分。如果每个事件问题独立计分，一个把顺序全搞反但把每个动作都拍出来了的视频会拿高分——这与「叙事连贯」的直觉相悖。所以需要一个把依赖关系编码进分数的机制：前置事件答错，后续事件就不给分。</p><p>第五步是验证指标本身。既然做了 2560 条人工标注，就用它算自动指标与人工判断的秩相关。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>视觉保真度和叙事连贯性是两个几乎不相关的能力，而现有 benchmark 只测前者，所以模型看起来一直在进步。要把后者测出来，关键不是看更多帧，而是<strong>先从文本里把事件依赖结构抽出来，再带着这个结构去看帧</strong>——问题从「这段视频好不好」变成「事件 B 是否在事件 A 之后发生且 A 的状态被正确继承」。依赖过滤则保证了分数具有链式性质：一环断了后面就不该算对，这才符合人对「故事讲通了」的判断。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「一个人打开搅拌机、放入水果、果汁溅出」这类 prompt 为例走一遍。</p><p><strong>数据集三维设计</strong>。内容类别四种：Animal（动物行为与互动）、Human（人类活动）、Object（无生命物体的变换与移动）、Imaginary（幻想或高度风格化内容）。难度四档：SSSA（单主体单动作，基线）、SSMA（单主体多动作，测时序顺序与状态转移）、MSSA（多主体单动作，测多实体的一致跟踪与协调）、MSMA（多主体多动作，测跨主体的协调与依赖）。时序关系三种：SS（严格顺序，每个动作必须完成后下一个才开始）、FO（灵活顺序，动作顺序可变但逻辑自洽）、SI（同时发生，测并行过程的协调）。组合下来是 4 大类 × 8 个子类 = 32 个子类别。</p><p><strong>prompt 构建三步走</strong>。其一，检索加描述——挑选体现目标动作模式的现有短视频片段，人工转写成保留时序关系的结构化文本。其二，人工头脑风暴——补充现实与想象场景，尤其服务 Imaginary 类别，同时保证幻想场景内部逻辑自洽。其三，LLM 驱动生成——引导大模型产出满足时序与难度规格的多步动作描述。三步共产出每子类 200 条、合计 6400 条原始 prompt。</p><p><strong>四条过滤规则</strong>：动作须能在 1–5 秒内完成且 prompt 不超过 77 token；不含声音、音乐等音频元素的描述；严格符合所分配的内容类别、难度与时序类型；不含术语与过度细节的描述。筛完得到 320 条均匀分布在各子类的高质量 prompt。</p><p><strong>视觉细节评估管线</strong>：先从代表性帧提取场景图，捕捉物体、属性与空间关系；再针对物体存在性、属性正确性、空间关系准确性、场景构图质量生成问题；最后用视觉问答对场景图作答，给出视觉保真度分数。</p><p><strong>叙事连贯性评估（DTG）</strong>：第一步时序分解——把 prompt 解析成形如 <code>(id, type, content)</code> 的时序元组，type 区分状态转移与动作事件，再在元组间建立时序依赖，构成表示叙事逻辑流的有向无环图。第二步动态图提取——这是核心创新：不用固定模板，而是<strong>根据每条视频各自的评估问题动态生成场景图提取 prompt</strong>。系统解析问题以识别哪些视觉特征、物体状态与时间变化最关键，再改写基础提取 prompt 强调这些元素。举例来说，若问题关注「杯子的满溢程度是否正确转变」，改写后的 prompt 会明确要求视觉模型密切关注容器类物体及其跨帧的填充状态。第三步多帧提取——用改写后的 prompt 在视频时间轴上均匀取帧（通常 15 帧）提场景图，每张图记录物体与实体的位置、动作状态、视觉属性、空间与语义关系及置信度。</p><p><strong>打分与聚合</strong>：每个时序问题给二值分（是 1.0、否 0.0），并施加<strong>依赖过滤</strong>——只有当与之相关的所有前置动作/物体的问题都答对时，该问题才计为正确。</p><p><strong>人工评估</strong>：招募 11 名有经验的参与者，在视觉质量与叙事连贯两个维度上用 3 点 Likert 量表（0 差、1 可接受、2 优秀）打分，每条视频由 5 人独立评估后取均值。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>评测对象是 8 个模型：Runway Gen3、Sora、Luma Ray2、Google Veo 2.0、CogVideo 1.5、Pika 2.2、Hailuo T2V-01、Kling 2.0。</p><p><strong>问题一：当前 T2V 在多事件叙事上到底有多差？</strong> 答案是一个刺眼的落差。视觉细节维度上所有模型都不错，Kling 2.0 均分 0.775、CogVideo 1.5 0.767、Hailuo 0.739、Pika 2.2 0.690、Sora 0.674、Luma Ray2 0.644、Veo 2.0 0.548、Gen3 0.484。切到叙事连贯维度，全线塌方：最好的 Kling 2.0 只有 0.252，Hailuo 0.231、Pika 2.2 0.228、CogVideo 1.5 0.217、Veo 2.0 0.201、Luma 0.180、Sora 0.178、Gen3 0.154。<strong>同一批模型在两个维度上相差三倍以上</strong>，这是全文最重要的一个数字对比：视觉质量的进步没有带来叙事能力的进步。</p><p><strong>问题二：这个自动指标可信吗？</strong> 论文报告 DTG 与人工标注的 Spearman 相关达 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.857</span></span></span></span>，分子类的相关系数在视觉维度上从 0.557（SSMA_SI）到 0.881（MSMA_SI），在叙事维度上从 0.619（SSMA_FO）到 0.970（MSMA_FO）。相关性总体较强，但在不同子类上波动明显。</p><p><strong>问题三：具体错在哪？</strong> 四类失败模式。其一，复杂度驱动的性能退化——prompt 要求复杂动作或多主体时性能骤降，MSMA_SS（多主体多动作且严格顺序）在所有模型上都是最低分；有意思的是 MSMA_SI（同时发生）反而比严格顺序略容易，说明模型协调并发动作比维持精确时序更轻松。其二，主体缺失与不一致——模型常生成比 prompt 指定更少的主体，偶尔更多；面对同时发生的多主体场景，模型采取「欺骗性」策略——不把所有主体放在同一帧，而是前几秒拍 A、然后切到 B、再切到 C，制造出「切镜头」效果而非真正的同时动作。其三，时序逻辑与动作协调失败——在需要逻辑顺序的场景里频繁出现<strong>时序倒置</strong>，比如果汁在搅拌机倾倒之前就洒了出来；复杂多步动作常常只执行了其中一两个；同时场景下模型倾向「丢动作」，退回更简单的单焦点叙事。其四，模型特异行为——Gen3 擅长自然场景与可信运动但常忽略 prompt 自行发挥；Sora 与 Pika 的人物渲染风格相近，都存在解剖学畸变（多出的肢体、扭曲的环境元素）；Veo 2.0 整体表现不错但有重复播放、跳帧、角色或物体突然消失等技术瑕疵。</p><p>从公开数据集路径（<code>Acmmm2025_video_benchmark</code>）可以推断这项工作面向 ACM MM 2025 投稿，但论文正文未给出接收信息，此处属于推断而非论文声称。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：SeqBench 用「内容类别 × 主体数与动作数 × 时序关系」三维分层设计了 320 条 prompt，配 8 个 SOTA 模型生成的 2560 条人工标注视频。核心发现是视觉质量与叙事连贯的巨大落差——最好的 Kling 2.0 视觉均分 0.775 而叙事均分仅 0.252，说明画质进步没有转化为序列推理能力。DTG 指标的做法是先把 prompt 解析成时序依赖 DAG，再用问题自适应的 prompt 从 15 帧提场景图，最后用依赖过滤打二值分，与人工判断的 Spearman 相关为 0.857。失败模式高度一致：多主体严格顺序最难，模型会用切镜头伪装同时动作、会把因果顺序倒置、会直接丢弃动作。这些不是画质问题，是模型没有把事件之间的依赖关系建模进生成过程。</p><p><strong>三句话版</strong>：多事件叙事是当前 T2V 最大的短板，且被现有以画质为中心的 benchmark 完全掩盖。把 prompt 结构化成事件依赖图、再带着这张图去看有限的几帧，可以在算力可承受的前提下测出顺序错误。测出来的结果是全线不及格，最好的模型也只有 0.25 量级。</p><p><strong>一句话版</strong>：模型能拍出漂亮的帧，但讲不通一件事，而这件事此前没人在量。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>DTG 分数低反映的是生成模型的叙事失败，而不是评估管线本身的测量失败</strong>。</p><p>这个假设承担了全文最重的论证负担，因为核心结论「所有模型的叙事连贯分都在 0.15–0.25 之间」几乎完全由这个指标产生。而这个指标的每一环都可能自己贡献误差。整条链路是：MLLM 从 15 帧提场景图 → 场景图对时序问题作答 → 二值打分 → 依赖过滤。</p><p>三处具体风险。第一，15 帧对一段包含 3–4 个动作的视频而言极稀疏，动作之间的过渡——恰恰是判断顺序对错的关键位置——很可能落在采样间隔里；论文自己在 §2 批评过依赖关键帧的方法会漏掉过渡细节，但均匀取 15 帧同样面临这个问题。第二，MLLM 从静态帧中判断「动作 A 是否已完成」本身就不可靠，而这是每一道时序问题的前提。第三也是最要命的，<strong>依赖过滤会把误差沿依赖链相乘</strong>：若单个问题的判定准确率是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span>，一条长度为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 的依赖链上全部正确的概率大致按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8588em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span> 衰减，即使 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span> 不算低，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 稍大分数就会被压到很低。这恰好能解释为什么所有模型的绝对分都落在 0.15–0.25 这个狭窄区间——它可能是指标的天花板而非模型的天花板。</p><p>论文提供的证据是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.857</span></span></span></span> 的秩相关。但秩相关只保证<strong>排序</strong>一致，对绝对值的校准毫无约束——一个把所有模型都压到 0.2 附近但保持相对次序的指标同样能拿到高秩相关。<strong>缺少的关键证据是</strong>：在人工标注为「叙事完全正确」的那批视频上，DTG 给出多少分。如果这批视频的 DTG 分数也只有 0.4，那么指标的上界问题就被坐实，「所有模型都很差」这个结论需要重述为「所有模型在这个指标下都很低」。这个测量用现有标注就能做，成本几乎为零。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，直接检验 §9 提出的指标上界问题，不需要生成任何视频。</p><ol><li><strong>数据</strong>：从 SeqBench 公开数据里取人工叙事连贯评分为 2（优秀）的那批视频，以及评分为 0（差）的那批，各取 100 条。</li><li><strong>额外构造一个「天花板集」</strong>：对同样的 320 条 prompt，人工从真实视频素材里剪辑出 20 条<strong>确实按 prompt 顺序发生</strong>的片段。这批的叙事连贯性按定义是满分。</li><li><strong>实现</strong>：复现 DTG 的打分部分即可——prompt 解析成依赖元组、按问题自适应改写提取 prompt、取 15 帧提场景图、二值打分加依赖过滤。用任一开源 MLLM。</li><li><strong>测量三组数字</strong>：天花板集上的 DTG 分数、人工评分为 2 的生成视频上的 DTG 分数、人工评分为 0 的上的 DTG 分数。同时记录每条视频的依赖链长度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span>，并按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 分组统计分数。</li><li><strong>判据</strong>：若天花板集的 DTG 分数接近 1.0，指标校准良好，论文结论成立；若天花板集只有 0.3–0.5，说明指标存在系统性低估，「模型叙事能力只有 0.25」这一表述需要改成相对比较而非绝对判断。若分数随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 呈现明显的幂律下降，则依赖过滤的误差累积效应被证实，应当改用对链长归一化的打分方式。</li></ol><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的攻击是给出一个<strong>替代解释：DTG 测出来的差异主要来自模型的「指令跟随」而非「叙事推理」</strong>。</p><p>论证如下。论文自己观察到 Gen3「常忽略 prompt 自行发挥」而它恰好是叙事分最低的（0.154）；Kling 2.0 叙事分最高（0.252）而它同时视觉分也最高（0.775）。两个维度的模型排序高度相似——视觉分前三是 Kling、CogVideo、Hailuo，叙事分前三是 Kling、Hailuo、Pika，重叠度很高。如果叙事连贯是一个与画质正交的独立能力，我们应当看到某些模型画质一般但叙事不错，或者反过来；实际数据里这种解耦很弱。这就打开了一个替代解释：DTG 分数主要由「模型有多听 prompt 的话」驱动，而这与是否理解事件依赖无关——一个完全不理解因果但逐字执行 prompt 的模型也能拿高分。</p><p>设计反例实验来切开这两者：构造<strong>顺序打乱的对照 prompt</strong>。取同一组事件，写成两个版本——版本 A 是物理因果正确的顺序（先倾倒搅拌机、后果汁溅出），版本 B 是把顺序颠倒的物理不可能版本（先果汁溅出、后倾倒搅拌机）。让模型分别生成，再用 DTG 打分。</p><p>判据很锋利。如果模型在版本 B 上的 DTG 分数与版本 A 相当，说明模型只是在机械执行文本顺序，没有任何因果理解，那么 SeqBench 测的确实是指令跟随；如果模型在版本 B 上系统性地「纠正」成了物理正确的顺序（因而 DTG 判为不符合 prompt 而扣分），反倒证明模型内部有物理先验且它压过了指令——这同样意味着低 DTG 分不能简单解读为「叙事能力差」。两种结果都会要求论文重新表述其结论，而当前的实验设计无法区分它们。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：SeqBench 是一个纯诊断工具——它告诉你模型在哪崩，但不提供任何可用于改进的信号。而 §9 揭示的问题更根本：依赖过滤把连贯性变成一个二值链式判定，这个分数不可微、方差大、且随链长指数衰减，因此没法当 reward 用。于是这个 benchmark 只能停在「发现问题」，无法推动「解决问题」。</p><p><strong>新的 framing</strong>：不要把叙事连贯当成对完成视频的<strong>事后评判</strong>，而当成对生成过程的<strong>在线状态一致性约束</strong>。也就是说，把 prompt 解析出的事件依赖 DAG 变成一个显式的状态机，在生成的每一段上维护「当前处于哪个事件节点、哪些状态变量已被改变」，并要求相邻段之间的状态转移合法。这是把评测问题重述成了一个带状态的生成问题，与「设计更好的指标」是不同的目标。</p><p><strong>可借鉴的相邻领域工具</strong>：一是任务与运动规划（TAMP）里的符号状态表示与前置/后置条件（precondition/effect）——它天然处理「动作 B 需要动作 A 的效果作为前提」这种依赖，而这正是 SeqBench 的 SS 类别在测的东西；二是受约束解码（constrained decoding）与自动机引导的生成，在语言模型里已被用于强制输出满足某个形式语言，其核心机制是用状态机在每一步裁剪采样空间。</p><p><strong>第一个实验长什么样</strong>：只做最窄的切口——SSMA_SS 子类（单主体、多动作、严格顺序），因为它的依赖结构最干净。第一步，把 40 条该子类 prompt 的事件依赖手工写成显式的前置/后置条件（例如「倾倒」的后置条件是容器姿态改变，是「溅出」的前置条件）。第二步，用现成的分段生成方式（把长 prompt 拆成逐段的图生视频）生成视频，每段生成后用 VLM 读取当前状态变量，检查是否满足下一段的前置条件；不满足就重采样该段。第三步，与直接一次性生成的对照组比较，用 SeqBench 的 DTG 与人工判断双重评估。判据是：如果状态机引导把该子类的人工叙事评分显著提升，说明连贯性失败的根源是缺少显式状态跟踪而非模型容量不足，那么正确的改进方向是给生成过程加状态记忆，而不是继续扩大模型；如果提升有限，说明失败发生在更底层——模型连单个动作的状态改变都渲染不对，此时该做的是先解决单事件的物理正确性，叙事层面的努力为时过早。这两个结论都比「模型叙事能力只有 0.25」更能指导后续工作。</p>',58)])])}const d=s(r,[["render",p]]);export{c as __pageData,d as default};
